import json

def classify_markers_v3(input_grid):
    h, w = len(input_grid), len(input_grid[0])

    # Find marker types and their column spans
    marker_info = {}  # val -> {'cols': set(), 'min_col': int, 'max_col': int, 'span_width': int}

    for r in range(h):
        for c in range(w):
            val = input_grid[r][c]
            if val not in [1, 9]:
                if val not in marker_info:
                    marker_info[val] = {'cols': set(), 'min_c': c, 'max_c': c}
                else:
                    marker_info[val]['cols'].add(c)
                    marker_info[val]['min_c'] = min(marker_info[val]['min_c'], c)
                    marker_info[val]['max_c'] = max(marker_info[val]['max_c'], c)

    third_w = w // 3

    classifications = {}
    for val, info in marker_info.items():
        cols = info['cols']
        min_c = info['min_c']
        max_c = info['max_c']

        # Check edge positions
        at_left_edge = min_c == 0
        at_right_edge = max_c >= 2 * third_w  # Touches or near right edge

        # Classify based on position
        if at_left_edge and at_right_edge:
            classifications[val] = 'full'  # Spans entire width
        elif at_left_edge and not at_right_edge and max_c <= third_w + 4:
            classifications[val] = 'left'  # Stays in left portion
        elif not at_left_edge and not at_right_edge and min_c >= third_w - 4:
            classifications[val] = 'center'  # In middle portion
        elif not at_left_edge and at_right_edge:
            classifications[val] = 'right'  # On right side
        else:
            classifications[val] = 'mixed'

    return classifications, marker_info

