import json

def classify_and_output(input_grid):
    h, w = len(input_grid), len(input_grid[0])

    # Get marker info
    marker_info = {}
    for r in range(h):
        for c in range(w):
            val = input_grid[r][c]
            if val not in [1, 9]:
                if val not in marker_info:
                    marker_info[val] = {'first_r': r, 'last_r': r, 'cols': {c}, 'min_c': c}
                else:
                    marker_info[val]['last_r'] = max(marker_info[val]['last_r'], r)
                    marker_info[val]['cols'].add(c)
                    marker_info[val]['min_c'] = min(marker_info[val]['min_c'], c)

    print("Marker info:")
    for val, info in sorted(marker_info.items(), key=lambda x: x[1]['first_r']):
        print(f"  {val}: first_r={info['first_r']}, cols={sorted(info['cols'])}, min_c={info['min_c']}")

    # Classify by minimum column position
    third_w = w // 3
    classifications = {}

    for val, info in marker_info.items():
        min_c = info['min_c']

        if min_c == 0:
            # Touches left edge - could be full or left
            # Check if it also reaches toward the right
            max_c = max(info['cols'])
            if max_c >= 2 * third_w:
                classifications[val] = 'full'
            elif max_c >= third_w + w//6:
                # Reaches past middle but not full - treat as "full" for output purposes
                classifications[val] = 'full'
            else:
                classifications[val] = 'left'
        elif min_c < third_w and max_c < 2*third_w:
            # Doesn't touch edges, in middle
            classifications[val] = 'center'
        else:
            classifications[val] = 'other'

    print("\nClassifications:", classifications)

    # Now build output
    output = []
    band_h = (h + 5) // 6

    for b in range(6):
        start_r = b * band_h
        end_r = min((b+1) * band_h, h)

        markers_in_band = set()
        marker_cols_this_band = {}

        for r in range(start_r, end_r):
            for c in range(w):
                val = input_grid[r][c]
                if val not in [1, 9]:
                    if val not in markers_in_band:
                        markers_in_band.add(val)
                        marker_cols_this_band[val] = c

        print(f"\nBand {b} ({start_r}-{end_r}): {sorted(markers_in_band)}")

        if not markers_in_band:
            output.append([9, 9, 9])
        else:
            ms = sorted(markers_in_band)

            # For each marker, check its classification and where it sits in THIS band
            results = []
            for m in ms:
                cls = classifications[m]
                min_c = marker_info[m]['min_c']

                if cls == 'full':
                    results.append(('full', m))
                elif cls == 'left' and min_c < third_w:
                    results.append(('left', m))
                elif cls == 'center' and min_c >= third_w:
                    results.append(('center', m))
                else:
                    results.append(('mixed', m))

            print(f"  Band results: {results}")

            # Build output row based on results
            if not results:
                output.append([9, 9, 9])
            elif len(results) == 1:
                typ, val = results[0]
                if typ == 'full':
                    output.append([val, val, val])
                elif typ == 'left':
                    output.append([val, 9, 9])
                elif typ == 'center':
                    output.append([9, val, 9])
                else:
                    output.append([9, val, 9])
            else:
                # Multiple markers - separate by left/center/right
                left_mks = [v for t, v in results if t == 'left' or t == 'mixed']
                center_mks = [v for t, v in results if t == 'center' or t == 'mixed']
                right_mks = [v for t, v in results if t == 'full']

                if left_mks and center_mks and right_mks:
                    output.append([left_mks[0], center_mks[0], right_mks[0]])
                elif left_mks and right_mks:
                    output.append([left_mks[0], 9, right_mks[0]])
                elif center_mks:
                    output.append([9, center_mks[0], 9])
                elif left_mks:
                    output.append([left_mks[0], 9, 9])
                else:
                    output.append([9, 9, 9])

    return output

