def compute_output_v4(input_grid):
    h, w = len(input_grid), len(input_grid[0])

    # Find all marker info
    marker_info = {}
    for r in range(h):
        for c in range(w):
            val = input_grid[r][c]
            if val not in [1, 9]:
                if val not in marker_info:
                    marker_info[val] = {'first': r, 'last': r, 'cols': {c}, 'min_c': c}
                else:
                    marker_info[val]['last'] = max(marker_info[val]['last'], r)
                    marker_info[val]['cols'].add(c)
                    marker_info[val]['min_c'] = min(marker_info[val]['min_c'], c)

    print("Marker info:")
    for v, m in sorted(marker_info.items(), key=lambda x: x[1]['first']):
        cls = 'full' if 0 in m['cols'] and max(m['cols']) > 13 else ('left' if m['min_c'] == 0 else 'center')
        print(f"  {v}: first={m['first']}, last={m['last']}, cols={sorted(m['cols'])} → {cls}")

    # Classify markers
    third_w = w // 3
    for v, m in marker_info.items():
        if 0 in m['cols'] and max(m['cols']) >= 13:  # Spans left and reaches past 2/3
            marker_info[v]['type'] = 'full'
        elif 0 in m['cols'] and m['min_c'] == 0:
            marker_info[v]['type'] = 'left'
        elif m['min_c'] >= 4 and max(m['cols']) <= 13:
            marker_info[v]['type'] = 'center'
        else:
            marker_info[v]['type'] = 'other'

    print("\nClassifications:")
    for v, m in marker_info.items():
        print(f"  {v}: {m['type']}")

    # Build output - 6 rows
    output = []
    band_h = (h + 5) // 6

    for b in range(6):
        start_r = b * band_h
        end_r = min((b+1) * band_h, h)

        # Find markers present in this band
        active_markers = []
        for v, m in marker_info.items():
            if m['first'] < end_r and m['last'] >= start_r:
                active_markers.append((m['type'], v))

        print(f"\nBand {b} ({start_r}-{end_r}): {active_markers}")

        if not active_markers:
            output.append([9, 9, 9])
        else:
            ms = sorted(active_markers, key=lambda x: marker_info[x[1]]['first'])

            results = []
            for typ, val in ms:
                first = marker_info[val]['first']
                last = marker_info[val]['last']

                if typ == 'left' and first < h / 3:
                    continue

                if typ == 'full' and last - first < h / 3:
                    continue

                results.append((typ, val))

            print(f"  After filtering: {results}")

            if not results:
                output.append([9, 9, 9])
            elif len(results) == 1:
                typ, val = results[0]
                if typ == 'full':
                    output.append([val, val, val])
                elif typ == 'left':
                    output.append([val, 9, 9])
                elif typ == 'center':
                    output.append([9, val, 9])
                else:
                    output.append([9, val, 9])
            else:
                types = set(t for t, v in results)
                if 'full' in types:
                    full_vals = [v for t, v in results if t == 'full']
                    other_vals = [v for t, v in results if t != 'full']

                    if other_vals and results[0][0] == 'left' and results[-1][0] == 'full':
                        output.append([results[0][1], 9, results[-1][1]])
                    else:
                        output.append([results[0][1], 9, full_vals[0]])
                elif 'left' in types:
                    left_vals = [v for t, v in results if t == 'left']
                    others = [v for t, v in results if t != 'left']
                    if left_vals and others:
                        output.append([left_vals[0], 9, others[0] if others else 9])
                    else:
                        output.append([left_vals[0], 9, 9])
                elif 'center' in types:
                    output.append([9, results[0][1], 9])
                else:
                    output.append([9, 9, 9])

    return output

