import json

# Simpler model: Each marker gets ONE output row based on its classification
# + fillers between them

def compute_output_simple(input_grid):
    h, w = len(input_grid), len(input_grid[0])

    # Find all marker info with correct span calc
    marker_info = {}
    for r in range(h):
        for c in range(w):
            val = input_grid[r][c]
            if val not in [1, 9]:
                if val not in marker_info:
                    marker_info[val] = {'first': r, 'last': r, 'cols': {c}, 'min_c': c}
                else:
                    marker_info[val]['last'] = max(marker_info[val]['last'], r)
                    marker_info[val]['cols'].add(c)
                    marker_info[val]['min_c'] = min(marker_info[val]['min_c'], c)

    # Classify: count how many distinct column positions each marker has
    third_w = w // 3

    classifications = {}
    for v, m in marker_info.items():
        cols = sorted(m['cols'])

        # Determine which thirds are occupied
        occupied = []
        for c in cols:
            if c < third_w:
                occupied.append('L')
            elif c < 2*third_w:
                occupied.append('M')
            else:
                occupied.append('R')

        unique_thirds = set(occupied)
        num_thirds = len(unique_thirds)

        if num_thirds >= 2:
            classifications[v] = 'full'
        elif 'L' in occupied and 'R' not in occupied:
            classifications[v] = 'left'
        elif 'M' in occupied and 'L' not in occupied and 'R' not in occupied:
            classifications[v] = 'center'
        elif 'R' in occupied:
            classifications[v] = 'right'
        else:
            classifications[v] = 'mixed'

    print("Classifications:")
    for v, cls in classifications.items():
        cols_str = str(sorted(marker_info[v]['cols']))
        print(f"  {v}: cols={cols_str}, → {cls}")

    # Map markers to output rows
    # Order by first appearance
    sorted_markers = sorted(marker_info.keys(), key=lambda v: marker_info[v]['first'])
    print(f"\nSorted markers: {sorted_markers}")

    output = []
    num_bands = 6

    # Assign markers to bands
    marker_band_map = {v: None for v in sorted_markers}

    # First marker → band 0
    if len(sorted_markers) > 0:
        marker_band_map[sorted_markers[0]] = 0

    # Second marker → band 2 (with one filler between)
    if len(sorted_markers) > 1:
        marker_band_map[sorted_markers[1]] = 2

    # Third marker → band 4 
    if len(sorted_markers) > 2:
        marker_band_map[sorted_markers[2]] = 4

    # Fourth marker (if any) → band 5
    if len(sorted_markers) > 3:
        marker_band_map[sorted_markers[3]] = 5

    # Fill other bands with [9,9,9]
    for b in range(num_bands):
        if b in marker_band_map.values():
            # Find marker(s) assigned to this band
            mkrs_in_band = [m for m, bm in marker_band_map.items() if bm == b]

            if not mkrs_in_band:
                output.append([9, 9, 9])
            else:
                ms = mkrs_in_band
                if len(ms) == 1:
                    m = ms[0]
                    typ = classifications[m]
                    if typ == 'full':
                        output.append([marker_info[m]['cols'][0], marker_info[m]['cols'][0], marker_info[m]['cols'][0]])
                    elif typ == 'left':
                        output.append([marker_info[m]['cols'][0], 9, 9])
                    elif typ == 'center':
                        output.append([9, marker_info[m]['cols'][0], 9])
                    else:
                        output.append([9, marker_info[m]['cols'][0], 9])
                else:
                    # Multiple markers in same band - combine!
                    typs = [classifications[m] for m in ms]
                    vals = [marker_info[m]['cols'][0] for m in ms]

                    if 'full' in typs:
                        full_m = next(m for m in ms if classifications[m] == 'full')
                        other_m = next((m for m in ms if m != full_m), None)

                        if other_m:
                            # Full goes rightmost
                            output.append([vals[0], 9, vals[1]])
                        else:
                            output.append([vals[0], vals[0], vals[0]])
                    elif 'left' in typs:
                        left_vals = [vals[i] for i, t in enumerate(typs) if t == 'left']
                        others = [vals[i] for i, t in enumerate(typs) if t != 'left']
                        if left_vals and others:
                            output.append([left_vals[0], 9, others[0] if others else 9])
                        else:
                            output.append([left_vals[0] if left_vals else 9, 9, 9])
                    else:
                        output.append([9, vals[0] if vals else 9, 9])
        else:
            output.append([9, 9, 9])

    return output

