def solve_transform(grid):
    """Transform input grid to 6x3 output following ARC pattern"""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    fill = grid[1][1]

    # Find markers
    marker_info = {}
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val not in [bg, fill]:
                if val not in marker_info:
                    marker_info[val] = {'rows': set(), 'cols': []}
                marker_info[val]['rows'].add(r)
                marker_info[val]['cols'].append(c)

    sorted_markers = sorted(marker_info.keys(), key=lambda v: min(marker_info[v]['rows']))
    num_bands = 6

    # Classify
    def classify(v, m):
        cols = sorted(set(m['cols']))
        if cols[0] == 0:
            return 'full'
        elif cols[-1] >= w - 3:
            return 'right'
        else:
            return 'center'

    classifications = {v: classify(v, marker_info[v]) for v in sorted_markers}

    # Calculate primaries by equal spacing
    n = len(sorted_markers)
    step = (num_bands - 1) // (n - 1) if n > 1 else 1
    primary_bands = [i * step for i in range(n)]
    marker_to_band = dict(zip(sorted_markers, primary_bands))

    # Calculate actual band spans
    marker_bands = {}
    for v in sorted_markers:
        bands = sorted([int(r * num_bands / h) for r in marker_info[v]['rows']])
        marker_bands[v] = bands

    # Last occurrence band
    last_bands = {v: max(marker_bands[v]) for v in sorted_markers}

    # Build output
    result = [[fill]*3 for _ in range(num_bands)]

    # Phase 1: Place in primary bands
    for m in sorted_markers:
        cls = classifications[m]
        pr = marker_to_band[m]
        if cls == 'full':
            result[pr] = [m, m, m]
        elif cls == 'center':
            result[pr] = [fill, m, fill]
        elif cls == 'right':
            result[pr] = [fill, fill, m]
        elif cls == 'left':
            result[pr] = [m, fill, fill]

    # Phase 2: Extensions
    for m in sorted_markers:
        cls = classifications[m]
        pr = marker_to_band[m]

        if cls == 'left':
            lb = last_bands[m]
            for b in range(pr + 1, min(lb + 1, num_bands)):
                if result[b][0] == fill:
